"""읽기·근거 선택·판단을 연결하는 게임 내부 조사 화면."""
import json
from investigation_content import CASES
JS = "\nconst IQ_STATE={};\nfunction iqState(i){return IQ_STATE[i]||(IQ_STATE[i]={seen:[],selected:[],choice:'',view:null,done:false,error:'',hints:0,tries:0});}\nfunction iqMark(t){const C={'가':'#DBEAFE;color:#1E40AF;border-color:#60A5FA','나':'#FEF3C7;color:#92400E;border-color:#FBBF24','다':'#DCFCE7;color:#166534;border-color:#4ADE80','라':'#F3E8FF;color:#6B21A8;border-color:#C084FC'};return esc(t).replace(/익명 판매자 ([가나다라])/g,(m,k)=>'<b style=\"border:2px solid;background:'+C[k]+';padding:1px 8px;border-radius:999px;white-space:nowrap;font-weight:900\">🕵️ 익명 판매자 '+k+'</b>');}\nfunction iqSource(source){\n // 게임마다 자료를 보여 주는 모양이 달라요: 중고거래는 '도토리마켓' 앱 화면, 노노그램은 감식 자료 카드.\n const th=(typeof IQ_THEME!=='undefined')?IQ_THEME:'';\n if(th==='market') return `<article style=\"max-width:460px;margin:14px auto;background:#1F2937;border-radius:30px;padding:10px;box-shadow:0 10px 24px #0004\"><div style=\"background:#FFF7ED;border-radius:22px;overflow:hidden\"><div style=\"background:#F97316;color:#fff;padding:10px 14px;font-weight:900\">🛍️ 도토리마켓 · ${iqMark(source[1])}</div><div style=\"padding:12px 14px\"><div style=\"background:#fff;border-radius:4px 16px 16px 16px;padding:10px 12px;box-shadow:0 1px 3px #0002;font-size:1.05rem;line-height:1.75\">${iqMark(source[2])}</div></div></div></article>`;\n if(th==='lab') return `<article style=\"position:relative;margin:16px 0;background:#FFFDF5;border:1px solid #E5DCC3;border-radius:6px;padding:16px 16px 12px;box-shadow:0 6px 14px #0002;transform:rotate(-.6deg)\"><span style=\"position:absolute;top:-10px;left:18px;background:#FDE68A;border:1px solid #E7C55A;padding:2px 10px;font-weight:900;font-size:.85rem;transform:rotate(-3deg)\">🏷️ 감식 자료</span><b style=\"font-size:1.05rem\">${iqMark(source[1])}</b><p style=\"font-size:1.05rem;line-height:1.75;margin:.5rem 0 0\">${iqMark(source[2])}</p></article>`;\n return `<article style=\"background:#f0f5f2;padding:14px;margin:12px 0;border-left:5px solid #39756b\"><b style=\"font-size:1.05rem\">${iqMark(source[1])}</b><p style=\"font-size:1.05rem;line-height:1.75;margin:.5rem 0 0\">${iqMark(source[2])}</p></article>`;\n}\nfunction iqHTML(i){\n const c=IQ_CASES[i],s=iqState(i);\n const source=c.sources.find(x=>x[0]===s.view);\n return `<section class=\"box\" style=\"border:2px solid #b9d2c7;border-radius:16px;padding:16px;margin:12px 0;overflow-wrap:anywhere\">\n <h3>${esc(c.title)}</h3><p>자료를 찾아 읽고, 서로 연결되는 근거를 골라 결론을 제출하세요. 정답 자료를 처음부터 모두 보여 주지는 않아요.</p>\n <div style=\"display:flex;gap:8px;flex-wrap:wrap\">${c.sources.map(x=>`<button onclick=\"iqOpen(${i},'${x[0]}')\" ${x[3]&&!s.seen.includes(x[3])?'disabled':''}>${s.seen.includes(x[0])?'✓ ':''}${iqMark(x[1])}${x[3]&&!s.seen.includes(x[3])?' · 앞선 자료 확인 후':''}</button>`).join('')}</div>\n ${source?iqSource(source):''}\n ${s.done?`<p style=\"background:#dff1e5;padding:12px\"><b>✓ 근거 연결 완료</b><br>${esc(c.lesson)}</p>`:`\n <p><b>${esc(c.question)}</b></p>\n <select aria-label=\"조사 ${i+1} 결론\" onchange=\"iqState(${i}).choice=this.value;render()\" style=\"width:100%;font:inherit;padding:10px;white-space:normal\"><option value=\"\">결론 선택</option>${c.options.map((v,k)=>`<option value=\"${k}\" ${String(k)===s.choice?'selected':''}>${esc(v)}</option>`).join('')}</select>\n ${s.choice!==''?'<p><b>선택한 결론:</b> '+esc(c.options[Number(s.choice)])+'</p>':''}\n <p><b>이 결론을 직접 뒷받침하는 자료 ${c.proof.length}개 선택</b></p>\n ${s.seen.length?c.sources.filter(x=>s.seen.includes(x[0])).map(x=>`<label style=\"display:block;padding:8px\"><input type=\"checkbox\" ${s.selected.includes(x[0])?'checked':''} onchange=\"iqSelect(${i},'${x[0]}',this.checked)\"> ${iqMark(x[1])}</label>`).join(''):'<p>먼저 위의 자료를 조사하세요.</p>'}\n <button onclick=\"iqCheck(${i})\">근거와 결론 제출</button> <button onclick=\"iqHint(${i})\">비교할 지점 힌트</button>\n <p role=\"status\" style=\"color:#9b361d;font-weight:700\">${esc(s.error)}</p>\n ${s.hints?`<p>💡 ${esc(c.hint)}</p>`:''}`}\n </section>`;\n}\nfunction iqOpen(i,k){const c=IQ_CASES[i],s=iqState(i),x=c.sources.find(x=>x[0]===k);if(!x||(x[3]&&!s.seen.includes(x[3])))return;if(!s.seen.includes(k))s.seen.push(k);s.view=k;render();}\nfunction iqSelect(i,k,on){const s=iqState(i);s.selected=s.selected.filter(x=>x!==k);if(on&&s.seen.includes(k))s.selected.push(k);}\nfunction iqHint(i){iqState(i).hints++;if(typeof iqHintUsed==='function')iqHintUsed(i);render();}\nfunction iqCheck(i){const s=iqState(i),c=IQ_CASES[i];if(s.done)return;\n if(s.choice===''||s.selected.length!==c.proof.length){s.error='결론과 필요한 수의 근거를 모두 선택하세요.';render();return;}\n s.tries++;\n const ok=Number(s.choice)===c.answer&&c.proof.every(k=>s.seen.includes(k)&&s.selected.includes(k));\n if(ok){s.done=true;s.error='';iqComplete(i);}\n else{s.error='아직 근거가 결론을 충분히 뒷받침하지 못해요. 자료의 익명 판매자 이름표·대상·확인 경로를 다시 비교하세요.';if(typeof iqWrong==='function')iqWrong(i);render();}\n}\nfunction iqReset(){for(const k of Object.keys(IQ_STATE))delete IQ_STATE[k];}\n"
def attach(html):
    payload=json.dumps(CASES,ensure_ascii=False).replace("<","\\u003c")
    return html.replace("<script>", "<script>\nconst IQ_CASES="+payload+";\n"+JS+"\n",1)
